(() => {
const root=OpenDeskTool.root, output=root.querySelector('#output');
root.querySelector('#refresh').addEventListener('click', async event=>{
 if(!event.isTrusted)return;
 try{
  const status=await OpenDeskSDK.browser.capabilities.getStatus({operation:'browser.contextMenu.register'});
  const all=await OpenDeskSDK.browser.capabilities.list();
  output.textContent=JSON.stringify({status,operationCount:all.length,operations:all.map(o=>({operation:o.operation,implementation:o.implementation,callableNow:o.status?.callableNow,reasonCode:o.status?.reasonCode}))},null,2);
 }catch(error){output.textContent=(error.code||'E_BROWSER')+': '+error.message;}
});
})();
